/**
 * Rechnungen-Tab — CRUD for student invoices (Iteration 30 rewrite).
 *
 * The invoice number is generated by the backend (RE-2026-0001). The
 * form only collects: lesson date, duration (min), price (CHF),
 * payment method (Bar/Rechnung/Kreditkarte/Twint), note, status.
 * Autosave on blur for existing rows. New row via the compact form
 * on top. A "PDF" button per row streams a formatted invoice PDF.
 */
import { useEffect, useMemo, useState } from "react";
import { Loader2, Trash2, Plus, Check, CircleDot, XCircle, FileDown, Mail, Archive, ChevronDown, Ban, RotateCcw, AlertCircle, BellRing, X, Calendar } from "lucide-react";
import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { api, formatApiError } from "@/lib/api";

const STATUS_META = {
  open:      { label: "Offen",     bg: "#fff7ed", text: "#c2410c", dot: "#f97316" },
  paid:      { label: "Bezahlt",   bg: "#dcfce7", text: "#166534", dot: "#16a34a" },
  cancelled: { label: "Storniert", bg: "#f5f5f4", text: "#57534e", dot: "#a8a29e" },
};

const PAYMENT_META = {
  bar:         { label: "Bar",         dot: "#84cc16" },
  rechnung:    { label: "Rechnung",    dot: "#0ea5e9" },
  kreditkarte: { label: "Kreditkarte", dot: "#8b5cf6" },
  twint:       { label: "Twint",       dot: "#0f172a" },
};

const formatDMY = (iso) => {
  if (!iso || typeof iso !== "string") return "—";
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : "—";
};

const money = (n) =>
  new Intl.NumberFormat("de-CH", {
    style: "currency",
    currency: "CHF",
    minimumFractionDigits: 2,
  }).format(Number(n) || 0);

const backendBase = (process.env.REACT_APP_BACKEND_URL || "").replace(/\/$/, "");

export default function InvoicesTab({ student }) {
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [downloading, setDownloading] = useState(null);
  const [sending, setSending] = useState(null);
  const [reminderOpen, setReminderOpen] = useState(null);    // invoice being mahned
  const [paidDatePrompt, setPaidDatePrompt] = useState(null); // { invoice, currentDate }
  const [draft, setDraft] = useState({
    lesson_date: new Date().toISOString().slice(0, 10),
    duration_min: 45,
    price_chf: "",
    item_title: "",
    payment_method: "bar",
    status: "open",
    note: "",
  });

  const load = async () => {
    try {
      const r = await api.get(`/students/${student.id}/invoices`);
      setInvoices(r.data);
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [student.id]);

  const totals = useMemo(() => {
    const t = { total: 0, open: 0, paid: 0 };
    for (const i of invoices) {
      const price = Number(i.price_chf) || 0;
      if (i.status === "cancelled") continue;
      t.total += price;
      if (i.status === "paid") t.paid += price;
      else if (i.status === "open") t.open += price;
    }
    return t;
  }, [invoices]);

  const createInvoice = async () => {
    if (!draft.price_chf || Number(draft.price_chf) <= 0) {
      toast.error("Bitte Preis angeben");
      return;
    }
    setCreating(true);
    try {
      await api.post(`/students/${student.id}/invoices`, {
        ...draft,
        price_chf: parseFloat(draft.price_chf) || 0,
        duration_min: parseInt(draft.duration_min, 10) || 0,
      });
      toast.success("Rechnung angelegt");
      setDraft({
        lesson_date: new Date().toISOString().slice(0, 10),
        duration_min: 45,
        price_chf: "",
        item_title: "",
        payment_method: "bar",
        status: "open",
        note: "",
      });
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setCreating(false);
    }
  };

  const patch = async (id, field, value) => {
    try {
      let v = value;
      if (field === "price_chf") v = parseFloat(value) || 0;
      else if (field === "duration_min") v = parseInt(value, 10) || 0;
      await api.patch(`/students/${student.id}/invoices/${id}`, { [field]: v });
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    }
  };

  const setStatus = async (invoice, next) => {
    if (next === invoice.status) return;
    // When flipping to "paid" open a date-picker so the admin can confirm
    // the Zahlungseingangs-Datum. Default = today.
    if (next === "paid") {
      setPaidDatePrompt({
        invoice,
        date: new Date().toISOString().slice(0, 10),
      });
      return;
    }
    await patch(invoice.id, "status", next);
  };

  const confirmPaid = async () => {
    if (!paidDatePrompt) return;
    const { invoice, date } = paidDatePrompt;
    try {
      await api.patch(`/students/${student.id}/invoices/${invoice.id}`, {
        status: "paid",
        paid_at: date || new Date().toISOString().slice(0, 10),
      });
      toast.success(`Als bezahlt markiert am ${date ? formatDMY(date) : "heute"}`);
      setPaidDatePrompt(null);
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    }
  };

  const cancelInvoice = async (inv) => {
    const reason = window.prompt(
      `Rechnung ${inv.number} stornieren?\n\nBitte kurze Storno-Notiz eintragen (optional):`,
      inv.storno_note || "",
    );
    if (reason === null) return;                 // Nutzer hat abgebrochen
    try {
      await api.patch(
        `/students/${student.id}/invoices/${inv.id}`,
        { status: "cancelled", storno_note: reason.trim() },
      );
      toast.success("Rechnung storniert");
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    }
  };

  const reactivateInvoice = async (inv) => {
    if (!window.confirm(
      `Storno der Rechnung ${inv.number} rückgängig machen?\nStatus wird auf „Offen" gesetzt.`
    )) return;
    try {
      await api.patch(
        `/students/${student.id}/invoices/${inv.id}`,
        { status: "open", storno_note: "" },
      );
      toast.success("Storno rückgängig gemacht");
      load();
    } catch (e) {
      toast.error(formatApiError(e));
    }
  };

  const downloadPdf = async (inv) => {
    setDownloading(inv.id);
    try {
      const res = await api.get(
        `/students/${student.id}/invoices/${inv.id}.pdf`,
        { responseType: "blob" },
      );
      const blob = new Blob([res.data], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${inv.number || "Rechnung"}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setDownloading(null);
    }
  };

  const sendEmail = async (inv) => {
    const defaultTo = student.email || "";
    const to = window.prompt(
      `Rechnung ${inv.number} per E-Mail an:`,
      defaultTo,
    );
    if (to === null) return;                     // cancelled
    if (!to.trim()) {
      toast.error("Bitte Empfänger-E-Mail angeben");
      return;
    }
    setSending(inv.id);
    try {
      await api.post(`/students/${student.id}/invoices/${inv.id}/email`, {
        to: to.trim(),
      });
      toast.success(`E-Mail an ${to.trim()} versendet`);
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setSending(null);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 text-sm text-[#78716c]">
        <Loader2 size={14} className="animate-spin" /> Lade Rechnungen …
      </div>
    );
  }

  return (
    <div data-testid="invoices-tab" className="space-y-6">
      <div>
        <h2 className="font-display text-3xl md:text-4xl leading-none tracking-tight">
          Rechnungen
        </h2>
        <p className="text-xs text-[#78716c] mt-2 flex flex-wrap items-center gap-3">
          <span>
            <span className="font-semibold text-[#0f172a]">{invoices.length}</span>{" "}
            {invoices.length === 1 ? "Rechnung" : "Rechnungen"}
          </span>
          <span className="text-[#a8a29e]">·</span>
          <span>
            <span className="font-semibold text-[#0f172a]" data-testid="invoices-total">
              {money(totals.total)}
            </span>{" "}
            gesamt
          </span>
          <span className="text-[#a8a29e]">·</span>
          <span className="text-[#c2410c] font-semibold" data-testid="invoices-open">
            {money(totals.open)} offen
          </span>
          <span className="text-[#a8a29e]">·</span>
          <span className="text-[#166534] font-semibold" data-testid="invoices-paid">
            {money(totals.paid)} bezahlt
          </span>
        </p>
      </div>

      {/* Create form */}
      <div className="bg-white border border-[#e7e5e4] rounded-2xl p-4">
        <div className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] mb-3">
          Neue Rechnung — Nr. wird automatisch generiert
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
          <FieldGroup label="Datum der Lektion">
            <input
              type="date"
              value={draft.lesson_date}
              onChange={(e) => setDraft({ ...draft, lesson_date: e.target.value })}
              data-testid="invoice-new-lesson-date"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            />
          </FieldGroup>
          <FieldGroup label="Dauer (min)">
            <input
              type="number"
              min={0}
              value={draft.duration_min}
              onChange={(e) => setDraft({ ...draft, duration_min: e.target.value })}
              data-testid="invoice-new-duration"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            />
          </FieldGroup>
          <FieldGroup label="Preis CHF">
            <input
              type="number"
              step="0.05"
              value={draft.price_chf}
              onChange={(e) => setDraft({ ...draft, price_chf: e.target.value })}
              placeholder="z. B. 120.00"
              data-testid="invoice-new-price"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            />
          </FieldGroup>
          <FieldGroup label="Zahlungsweise">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button
                  type="button"
                  data-testid="invoice-new-payment-method"
                  className="w-full inline-flex items-center justify-between gap-2 text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36] hover:border-[#cbd5e1]"
                >
                  <span className="inline-flex items-center gap-2 truncate">
                    <span
                      className="inline-block w-2 h-2 rounded-full shrink-0"
                      style={{ background: PAYMENT_META[draft.payment_method]?.dot || "#94a3b8" }}
                    />
                    {PAYMENT_META[draft.payment_method]?.label || "—"}
                  </span>
                  <ChevronDown size={13} className="opacity-50 shrink-0" />
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start" className="min-w-[160px]">
                {Object.entries(PAYMENT_META).map(([k, v]) => (
                  <DropdownMenuItem
                    key={k}
                    data-testid={`invoice-new-payment-method-option-${k}`}
                    onClick={() => setDraft({ ...draft, payment_method: k })}
                    className="text-sm cursor-pointer"
                  >
                    <span
                      className="inline-block w-2 h-2 rounded-full mr-2"
                      style={{ background: v.dot }}
                    />
                    {v.label}
                    {draft.payment_method === k && (
                      <Check size={12} className="ml-auto text-[#166534]" />
                    )}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </FieldGroup>
        </div>
        <div className="mt-3 grid grid-cols-1 sm:grid-cols-[1fr_180px_auto] gap-3 items-end">
          <FieldGroup label="Titel (optional — z. B. Kurs «Fahren mit Blinden»)">
            <input
              type="text"
              value={draft.item_title}
              onChange={(e) => setDraft({ ...draft, item_title: e.target.value })}
              placeholder="Leer lassen → Fahrstunde"
              data-testid="invoice-new-item-title"
              maxLength={200}
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            />
          </FieldGroup>
          <FieldGroup label="Status">
            <select
              value={draft.status}
              onChange={(e) => setDraft({ ...draft, status: e.target.value })}
              data-testid="invoice-new-status"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
            >
              <option value="open">Offen</option>
              <option value="paid">Bezahlt</option>
              <option value="cancelled">Storniert</option>
            </select>
          </FieldGroup>
          <button
            type="button"
            onClick={createInvoice}
            disabled={creating}
            data-testid="invoice-create-button"
            className="inline-flex items-center justify-center gap-1.5 text-xs font-semibold tracking-widest uppercase bg-[#ff5a36] text-white px-5 py-2.5 rounded-lg hover:opacity-90 disabled:opacity-50 whitespace-nowrap"
          >
            {creating ? <Loader2 size={12} className="animate-spin" /> : <Plus size={12} />}
            Anlegen
          </button>
        </div>
        <div className="mt-3">
          <FieldGroup label="Bemerkungen (optional)">
            <textarea
              rows={2}
              value={draft.note}
              onChange={(e) => setDraft({ ...draft, note: e.target.value })}
              placeholder="z. B. Sehr geehrte Damen und Herren, gerne sende ich Ihnen… (bis 5 Zeilen sichtbar auf dem PDF)"
              data-testid="invoice-new-note"
              className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36] resize-none"
            />
          </FieldGroup>
        </div>
      </div>

      {/* Invoice rows */}
      {invoices.length === 0 && (
        <div className="bg-white border border-dashed border-[#e7e5e4] rounded-2xl p-10 text-center text-sm text-[#78716c]">
          Noch keine Rechnung erstellt.
        </div>
      )}

      <div className="space-y-2.5">
        {invoices.map((inv) => {
          const st = STATUS_META[inv.status] || STATUS_META.open;
          const isCancelled = inv.status === "cancelled";
          return (
            <div
              key={inv.id}
              data-testid={`invoice-row-${inv.id}`}
              data-status={inv.status}
              className={
                "border rounded-2xl p-4 transition-colors " +
                (isCancelled
                  ? "bg-[#fef2f2] border-[#fecaca] text-[#991b1b] [&_input]:!text-[#991b1b] [&_input]:line-through [&_.font-semibold]:line-through [&_[data-testid^='invoice-number-']]:line-through"
                  : "bg-white border-[#e7e5e4]")
              }
            >
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 items-start">
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Rechnungsnr.
                  </label>
                  <div
                    className="text-sm font-semibold text-[#0f172a]"
                    data-testid={`invoice-number-${inv.id}`}
                  >
                    {inv.number || "—"}
                  </div>
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Datum Lektion
                  </label>
                  <input
                    type="date"
                    defaultValue={inv.lesson_date}
                    onBlur={(e) => e.target.value !== inv.lesson_date && patch(inv.id, "lesson_date", e.target.value)}
                    data-testid={`invoice-lesson-date-${inv.id}`}
                    className="text-sm border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36] w-full min-w-0"
                  />
                  <div className="text-[10px] text-[#a8a29e]">{formatDMY(inv.lesson_date)}</div>
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Dauer
                  </label>
                  <div className="flex items-baseline">
                    <input
                      type="number"
                      min={0}
                      defaultValue={inv.duration_min}
                      onBlur={(e) => Number(e.target.value) !== Number(inv.duration_min) && patch(inv.id, "duration_min", e.target.value)}
                      data-testid={`invoice-duration-${inv.id}`}
                      className="text-sm border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36] w-16"
                    />
                    <span className="text-[10px] text-[#a8a29e] ml-1">min</span>
                  </div>
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Preis CHF
                  </label>
                  <input
                    type="number"
                    step="0.05"
                    defaultValue={inv.price_chf}
                    onBlur={(e) => Number(e.target.value) !== Number(inv.price_chf) && patch(inv.id, "price_chf", e.target.value)}
                    data-testid={`invoice-price-${inv.id}`}
                    className="text-sm font-semibold text-[#0f172a] border-0 bg-transparent focus:outline-none focus:border-b focus:border-[#ff5a36] w-full min-w-0"
                  />
                </div>
                <div>
                  <label className="text-[9px] tracking-widest uppercase text-[#94a3b8] block">
                    Zahlungsweise
                  </label>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <button
                        type="button"
                        data-testid={`invoice-payment-method-${inv.id}`}
                        className="w-full inline-flex items-center justify-between gap-1.5 text-sm bg-transparent hover:bg-[#fafaf9] rounded px-1 py-0.5 -ml-1 focus:outline-none focus:bg-[#fafaf9]"
                      >
                        <span className="inline-flex items-center gap-1.5 truncate">
                          <span
                            className="inline-block w-2 h-2 rounded-full shrink-0"
                            style={{ background: PAYMENT_META[inv.payment_method]?.dot || "#94a3b8" }}
                          />
                          {PAYMENT_META[inv.payment_method]?.label || "—"}
                        </span>
                        <ChevronDown size={12} className="opacity-50 shrink-0" />
                      </button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="min-w-[150px]">
                      {Object.entries(PAYMENT_META).map(([k, v]) => (
                        <DropdownMenuItem
                          key={k}
                          data-testid={`invoice-payment-method-${inv.id}-option-${k}`}
                          onClick={() => k !== inv.payment_method && patch(inv.id, "payment_method", k)}
                          className="text-sm cursor-pointer"
                        >
                          <span
                            className="inline-block w-2 h-2 rounded-full mr-2"
                            style={{ background: v.dot }}
                          />
                          {v.label}
                          {inv.payment_method === k && (
                            <Check size={12} className="ml-auto text-[#166534]" />
                          )}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </div>

              {/* Row 2: status · note · actions */}
              <div className="mt-3 pt-3 border-t border-[#f3f0eb] flex flex-wrap items-center gap-3">
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button
                      data-testid={`invoice-status-${inv.id}`}
                      className="inline-flex items-center gap-1.5 text-[10px] font-semibold tracking-widest uppercase px-3 py-1.5 rounded-full transition-colors shrink-0 hover:opacity-90"
                      style={{ background: st.bg, color: st.text }}
                      title="Status ändern"
                    >
                      {inv.status === "paid" && <Check size={11} strokeWidth={3} />}
                      {inv.status === "open" && <CircleDot size={11} />}
                      {inv.status === "cancelled" && <XCircle size={11} />}
                      {st.label}
                      {inv.status === "paid" && inv.paid_at && (
                        <span className="ml-1 opacity-70 font-normal normal-case tracking-normal">
                          · {formatDMY(inv.paid_at)}
                        </span>
                      )}
                      <ChevronDown size={11} className="opacity-60" />
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="start" className="min-w-[140px]">
                    {Object.entries(STATUS_META).map(([key, meta]) => (
                      <DropdownMenuItem
                        key={key}
                        data-testid={`invoice-status-${inv.id}-option-${key}`}
                        onClick={() => setStatus(inv, key)}
                        className="text-xs font-semibold tracking-widest uppercase cursor-pointer"
                      >
                        <span
                          className="inline-block w-2 h-2 rounded-full mr-2"
                          style={{ background: meta.dot }}
                        />
                        {meta.label}
                        {inv.status === key && (
                          <Check size={12} className="ml-auto text-[#166534]" />
                        )}
                      </DropdownMenuItem>
                    ))}
                  </DropdownMenuContent>
                </DropdownMenu>
                {inv.reminder_level > 0 && (
                  <span
                    data-testid={`invoice-reminder-badge-${inv.id}`}
                    className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase bg-[#fef3c7] text-[#92400e] border border-[#fde68a] px-2.5 py-1 rounded-full shrink-0"
                    title={`Letzte Mahnung: ${inv.last_reminder_at ? new Date(inv.last_reminder_at).toLocaleDateString("de-CH") : "—"}${inv.reminder_fee_chf ? ` · Gebühren CHF ${Number(inv.reminder_fee_chf).toFixed(2)}` : ""}`}
                  >
                    <BellRing size={10} /> {inv.reminder_level}. Mahnung
                  </span>
                )}
                <input
                  type="text"
                  defaultValue={inv.item_title || ""}
                  onBlur={(e) => (e.target.value || "") !== (inv.item_title || "") && patch(inv.id, "item_title", e.target.value)}
                  data-testid={`invoice-item-title-${inv.id}`}
                  placeholder="Titel (leer = Fahrstunde)"
                  maxLength={200}
                  className="w-[220px] max-w-[220px] text-sm text-[#334155] border-0 bg-[#fafaf9] rounded-lg px-3 py-1.5 focus:outline-none focus:bg-white focus:ring-1 focus:ring-[#ff5a36]"
                />
                <input
                  type="text"
                  defaultValue={inv.note}
                  onBlur={(e) => e.target.value !== inv.note && patch(inv.id, "note", e.target.value)}
                  data-testid={`invoice-note-${inv.id}`}
                  placeholder="Bemerkungen (optional)"
                  className="flex-1 min-w-[120px] text-sm text-[#334155] border-0 bg-[#fafaf9] rounded-lg px-3 py-1.5 focus:outline-none focus:bg-white focus:ring-1 focus:ring-[#ff5a36]"
                />
                {isCancelled && (
                  <input
                    type="text"
                    defaultValue={inv.storno_note || ""}
                    onBlur={(e) => (e.target.value || "") !== (inv.storno_note || "") && patch(inv.id, "storno_note", e.target.value)}
                    data-testid={`invoice-storno-note-${inv.id}`}
                    placeholder="Storno-Notiz (Grund)"
                    maxLength={500}
                    className="w-[220px] max-w-[220px] text-sm text-[#991b1b] no-underline border border-[#fecaca] bg-white rounded-lg px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-[#dc2626] placeholder-[#dc262699]"
                    style={{ textDecoration: "none" }}
                  />
                )}
                <div className="flex items-center gap-1 shrink-0 ml-auto">
                  <button
                    onClick={() => downloadPdf(inv)}
                    disabled={downloading === inv.id}
                    data-testid={`invoice-download-pdf-${inv.id}`}
                    className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase bg-[#0f172a] text-white px-3 py-2 rounded-full hover:opacity-90 disabled:opacity-40"
                  >
                    {downloading === inv.id ? (
                      <Loader2 size={11} className="animate-spin" />
                    ) : (
                      <FileDown size={11} />
                    )}
                    PDF
                  </button>
                  {inv.archive_url && (
                    <a
                      href={`${backendBase}${inv.archive_url}`}
                      target="_blank"
                      rel="noreferrer"
                      data-testid={`invoice-archive-${inv.id}`}
                      title={`Aus Archiv laden – ${inv.archived_at?.slice(0, 10) || ""}`}
                      className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase text-[#475569] bg-white border border-[#e2e8f0] px-2.5 py-2 rounded-full hover:text-[#0f172a] hover:border-[#0f172a]"
                    >
                      <Archive size={11} />
                    </a>
                  )}
                  <button
                    onClick={() => sendEmail(inv)}
                    disabled={sending === inv.id}
                    data-testid={`invoice-send-email-${inv.id}`}
                    className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase bg-[#ff5a36] text-white px-3 py-2 rounded-full hover:opacity-90 disabled:opacity-40"
                    title="Rechnung per E-Mail senden"
                  >
                    {sending === inv.id ? (
                      <Loader2 size={11} className="animate-spin" />
                    ) : (
                      <Mail size={11} />
                    )}
                    E-Mail
                  </button>
                  {inv.status === "open" && !inv.is_direct && (
                    <button
                      onClick={() => setReminderOpen(inv)}
                      data-testid={`invoice-reminder-${inv.id}`}
                      className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase bg-[#f59e0b] text-white px-3 py-2 rounded-full hover:opacity-90"
                      title={inv.reminder_level >= 3 ? "Bereits 3 Mahnungen versendet" : "Mahnung senden"}
                    >
                      <BellRing size={11} />
                      Mahnung
                    </button>
                  )}
                  {inv.status === "cancelled" ? (
                    <button
                      onClick={() => reactivateInvoice(inv)}
                      data-testid={`invoice-reactivate-${inv.id}`}
                      title='Storno rückgängig — Status auf „Offen" setzen'
                      className="inline-flex items-center gap-1 text-[10px] font-semibold tracking-widest uppercase bg-white border border-[#e2e8f0] text-[#475569] px-2.5 py-2 rounded-full hover:text-[#0f172a] hover:border-[#0f172a]"
                    >
                      <RotateCcw size={11} />
                      Reaktivieren
                    </button>
                  ) : (
                    <button
                      onClick={() => cancelInvoice(inv)}
                      data-testid={`invoice-cancel-${inv.id}`}
                      title="Rechnung stornieren (kann nicht mehr gelöscht werden)"
                      className="w-8 h-8 flex items-center justify-center rounded-full text-[#a8a29e] hover:text-[#dc2626] hover:bg-[#fee2e2]"
                    >
                      <Ban size={13} />
                    </button>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
      {paidDatePrompt && (
        <PaidDateModal
          value={paidDatePrompt.date}
          invoiceNumber={paidDatePrompt.invoice.number}
          onChange={(d) => setPaidDatePrompt((p) => ({ ...p, date: d }))}
          onCancel={() => setPaidDatePrompt(null)}
          onConfirm={confirmPaid}
        />
      )}
      {reminderOpen && (
        <ReminderModal
          student={student}
          invoice={reminderOpen}
          onClose={() => setReminderOpen(null)}
          onSent={() => { setReminderOpen(null); load(); }}
        />
      )}
    </div>
  );
}

function FieldGroup({ label, children }) {
  return (
    <div>
      <label className="text-[10px] tracking-widest uppercase text-[#475569] font-semibold block mb-1">
        {label}
      </label>
      {children}
    </div>
  );
}

/** Small modal that asks for the payment-received date when flipping to "paid". */
function PaidDateModal({ value, onChange, onCancel, onConfirm, invoiceNumber }) {
  return (
    <div
      data-testid="paid-date-modal"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
      onClick={onCancel}
    >
      <div
        className="bg-white rounded-2xl max-w-sm w-full p-6 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-start gap-3 mb-4">
          <div className="w-10 h-10 rounded-full bg-[#dcfce7] text-[#15803d] flex items-center justify-center shrink-0">
            <Check size={20} />
          </div>
          <div className="flex-1">
            <h3 className="font-display text-xl leading-tight text-[#0f172a]">
              Zahlungseingang
            </h3>
            <p className="text-sm text-[#475569] mt-1">
              Wann ist die Zahlung für {invoiceNumber} eingetroffen?
            </p>
          </div>
          <button
            onClick={onCancel}
            data-testid="paid-date-close"
            className="text-[#94a3b8] hover:text-[#0f172a] p-1"
          >
            <X size={18} />
          </button>
        </div>
        <label className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] block mb-1">
          Bezahlt am
        </label>
        <input
          type="date"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          data-testid="paid-date-input"
          className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36] mb-5"
        />
        <div className="flex items-center justify-end gap-2">
          <button
            onClick={onCancel}
            data-testid="paid-date-cancel"
            className="text-xs font-semibold tracking-widest uppercase px-4 py-2 rounded-full text-[#475569] hover:bg-[#f1f5f9]"
          >
            Abbrechen
          </button>
          <button
            onClick={onConfirm}
            data-testid="paid-date-confirm"
            className="inline-flex items-center gap-1.5 text-xs font-semibold tracking-widest uppercase bg-[#16a34a] text-white px-4 py-2 rounded-full hover:opacity-90"
          >
            <Check size={12} /> Als bezahlt markieren
          </button>
        </div>
      </div>
    </div>
  );
}

/** Modal that previews and sends a payment reminder (Mahnung). */
function ReminderModal({ student, invoice, onClose, onSent }) {
  const [level, setLevel] = useState(null);
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("");
  const [fee, setFee] = useState(0);
  const [to, setTo] = useState(student.email || "");
  const [daysOverdue, setDaysOverdue] = useState(0);
  const [previewing, setPreviewing] = useState(true);
  const [sending, setSendingLoc] = useState(false);

  useEffect(() => {
    (async () => {
      setPreviewing(true);
      try {
        const r = await api.post(
          `/students/${student.id}/invoices/${invoice.id}/reminder/preview`,
          { level: level || undefined },
        );
        setLevel(r.data.level);
        setSubject(r.data.subject);
        setBody(r.data.body);
        setFee(r.data.fee);
        setDaysOverdue(r.data.days_overdue);
        setTo(r.data.to || student.email || "");
      } catch (e) {
        toast.error(formatApiError(e));
      } finally {
        setPreviewing(false);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [level]);

  const send = async () => {
    if (!to.trim()) {
      toast.error("Empfänger-E-Mail fehlt");
      return;
    }
    setSendingLoc(true);
    try {
      await api.post(`/students/${student.id}/invoices/${invoice.id}/reminder`, {
        level,
        to: to.trim(),
        subject,
        body,
        fee,
      });
      toast.success(`${level}. Mahnung an ${to.trim()} versendet`);
      onSent?.();
    } catch (e) {
      toast.error(formatApiError(e));
    } finally {
      setSendingLoc(false);
    }
  };

  return (
    <div
      data-testid="reminder-modal"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-2xl max-w-2xl w-full p-6 shadow-2xl max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-start gap-3 mb-4">
          <div className="w-10 h-10 rounded-full bg-[#fef3c7] text-[#b45309] flex items-center justify-center shrink-0">
            <BellRing size={20} />
          </div>
          <div className="flex-1">
            <h3 className="font-display text-xl leading-tight text-[#0f172a]">
              Mahnung senden
            </h3>
            <p className="text-sm text-[#475569] mt-1">
              Rechnung <strong>{invoice.number}</strong> · {daysOverdue} Tage überfällig
              {invoice.reminder_level > 0 && (
                <span className="ml-2 text-[#b45309]">
                  · Bisherige Mahnungen: {invoice.reminder_level}
                </span>
              )}
            </p>
          </div>
          <button
            onClick={onClose}
            data-testid="reminder-modal-close"
            className="text-[#94a3b8] hover:text-[#0f172a] p-1"
          >
            <X size={18} />
          </button>
        </div>

        {/* Level selector */}
        <div className="mb-4">
          <label className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] block mb-2">
            Mahnstufe
          </label>
          <div className="inline-flex gap-1 bg-[#f8fafc] border border-[#e2e8f0] rounded-full p-1">
            {[1, 2, 3].map((n) => (
              <button
                key={n}
                onClick={() => setLevel(n)}
                data-testid={`reminder-level-${n}`}
                className={`text-[10px] font-semibold tracking-widest uppercase px-4 py-1.5 rounded-full transition-colors ${
                  level === n
                    ? "bg-[#f59e0b] text-white"
                    : "text-[#78716c] hover:text-[#0f172a]"
                }`}
              >
                {n === 1 ? "1. Mahnung" : n === 2 ? "2. Mahnung" : "3. Mahnung"}
              </button>
            ))}
          </div>
        </div>

        {previewing ? (
          <div className="flex items-center gap-2 text-sm text-[#78716c] py-8">
            <Loader2 size={14} className="animate-spin" /> Vorlage wird geladen …
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-4">
              <div>
                <label className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] block mb-1">
                  Empfänger
                </label>
                <input
                  type="email"
                  value={to}
                  onChange={(e) => setTo(e.target.value)}
                  data-testid="reminder-to"
                  className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
                />
              </div>
              <div>
                <label className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] block mb-1">
                  Mahngebühr (CHF)
                </label>
                <input
                  type="number"
                  step="0.05"
                  min="0"
                  value={fee}
                  onChange={(e) => setFee(parseFloat(e.target.value) || 0)}
                  data-testid="reminder-fee"
                  className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
                />
              </div>
            </div>
            <div className="mb-3">
              <label className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] block mb-1">
                Betreff
              </label>
              <input
                type="text"
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                data-testid="reminder-subject"
                className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36]"
              />
            </div>
            <div className="mb-5">
              <label className="text-[10px] font-semibold tracking-widest uppercase text-[#475569] block mb-1">
                Nachricht
              </label>
              <textarea
                rows={10}
                value={body}
                onChange={(e) => setBody(e.target.value)}
                data-testid="reminder-body"
                className="w-full text-sm bg-[#fbf9f6] border border-[#e2e8f0] rounded-lg px-3 py-2 focus:outline-none focus:border-[#ff5a36] font-mono resize-none"
              />
              <p className="text-[10px] text-[#94a3b8] mt-1">
                Standard-Text bearbeitbar unter Admin → Mail → E-Mail Einstellungen.
              </p>
            </div>
            <div className="bg-[#fff7ed] border border-[#fed7aa] rounded-xl p-3 text-xs text-[#9a3412] mb-4 flex items-start gap-2">
              <AlertCircle size={14} className="shrink-0 mt-0.5" />
              <div>
                Die Mahnung wird per E-Mail versendet, mit einer aktualisierten Rechnungs-PDF (inkl. Mahngebühr) als Anhang.
                Der Status der Rechnung bleibt „offen", die Mahnstufe wird auf <strong>{level}</strong> gesetzt.
              </div>
            </div>
          </>
        )}

        <div className="flex items-center justify-end gap-2">
          <button
            onClick={onClose}
            data-testid="reminder-cancel"
            className="text-xs font-semibold tracking-widest uppercase px-4 py-2 rounded-full text-[#475569] hover:bg-[#f1f5f9]"
          >
            Abbrechen
          </button>
          <button
            onClick={send}
            disabled={previewing || sending}
            data-testid="reminder-send"
            className="inline-flex items-center gap-1.5 text-xs font-semibold tracking-widest uppercase bg-[#f59e0b] text-white px-5 py-2.5 rounded-full hover:opacity-90 disabled:opacity-50"
          >
            {sending ? <Loader2 size={12} className="animate-spin" /> : <BellRing size={12} />}
            Mahnung senden
          </button>
        </div>
      </div>
    </div>
  );
}
